import json
import re
from docx import Document

# Load employee data
with open('employee_data.json', 'r') as f:
    data = json.load(f)

# Load the template
doc = Document('offer_letter_template.docx')

def process_conditional(text, data):
    """Handle IF_RELOCATION conditional sections."""
    if data.get('RELOCATION_PACKAGE', '').lower() == 'yes':
        # Keep content, remove markers
        text = re.sub(r'\{\{IF_RELOCATION\}\}', '', text)
        text = re.sub(r'\{\{END_IF_RELOCATION\}\}', '', text)
    else:
        # Remove entire conditional section including content
        text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text, flags=re.DOTALL)
    return text

def replace_placeholders(text, data):
    """Replace all {{KEY}} placeholders with values from data."""
    # First handle conditionals
    text = process_conditional(text, data)

    # Then replace all placeholders
    pattern = r'\{\{([A-Z_]+)\}\}'
    def replacer(match):
        key = match.group(1)
        return str(data.get(key, match.group(0)))

    return re.sub(pattern, replacer, text)

def process_paragraph(para, data):
    """Process a single paragraph, handling split placeholders."""
    text = para.text
    new_text = replace_placeholders(text, data)

    if new_text != text:
        runs = para.runs
        if runs:
            runs[0].text = new_text
            for run in runs[1:]:
